  pointer-events: none !important; /* 点击穿透 */
  z-index: 0 !important; /* 堆叠层级 */
}

/* 按钮浮在背景图上面 */
.input-btn-mic,
.input-btn-ai,
.input-btn-sticker,
.input-btn-plus {
