.input-btn-ai:active {
    opacity: 1 !important;
}
/* 🤍 调整 AI 按钮位置：修改 .input-btn-ai 的 right 和 top（或 transform） */

/* ---------- 麦克风按钮 ---------- */
.input-btn-mic {
