[data-theme-style="qq"] .bubble-me-custom:has(.msg-transfer-card, .msg-loc-card, .gift-ig-container, .msg-theater-card, .msg-offline-invite-card, .msg-couples-invite-card, .msg-couples-response-card, .msg-werewolf-card, .msg-mahjong-card, .msg-test-invite-card, .msg-test-result-card, .msg-forum-share-card, .msg-sim-card)::after,
[data-theme-style="qq"] .bubble-them-custom:has(.msg-transfer-card, .msg-loc-card, .gift-ig-container, .msg-theater-card, .msg-offline-invite-card, .msg-couples-invite-card, .msg-couples-response-card, .msg-werewolf-card, .msg-mahjong-card, .msg-test-invite-card, .msg-test-result-card, .msg-forum-share-card, .msg-sim-card)::before,
