/* ===== 更多菜单 - iOS 风格深色液态玻璃 ===== */

.input-area-custom .more-options-popup {
    overflow: hidden !important;
    /* 吃緊平台會關掉 blur（native-degrade.css），所以底色本身要夠實，
       不然關 blur 後會透出底下聊天內容 */
    background: rgba(30, 30, 32, 0.94) !important;
    backdrop-filter: blur(30px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(30px) saturate(180%) !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
    border-radius: 14px !important;
    box-shadow:
        0 10px 40px rgba(0, 0, 0, 0.35),
        inset 0 1px 0 rgba(255, 255, 255, 0.12) !important;
    padding: 6px !important;
}
.input-area-custom .more-options-item-row {
    transition: background 0.15s ease !important;
    border-radius: 8px !important;
    padding: 10px 12px !important;
    background: transparent !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;
}
.input-area-custom .more-options-item-row:last-child {
    border-bottom: none !important;
}
.input-area-custom .more-options-item-row:hover,
.input-area-custom .more-options-item-row:active {
    background: rgba(255, 255, 255, 0.12) !important;
}
.input-area-custom .more-options-item-row span,
.input-area-custom .more-options-item-row * {
    color: #ffffff !important;
    font-size: 14px !important;
    font-weight: 500 !important;
    text-shadow: 0 0.5px 1px rgba(0, 0, 0, 0.25) !important;
}
.input-area-custom .more-options-item-row svg {
    color: #ffffff !important;
    stroke: #ffffff !important;
    opacity: 0.95;
    filter: drop-shadow(0 0.5px 1px rgba(0, 0, 0, 0.2));
}

/* 更多菜单改成限高可滚动后：主题原本的 overflow:hidden 会让内容滚不动 */
.input-area-custom .more-options-popup-scroll {
    overflow-y: auto !important;
    scrollbar-width: thin;
}
.input-area-custom .more-options-popup-scroll::-webkit-scrollbar {
    width: 4px;
}
.input-area-custom .more-options-popup-scroll::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.25);
    border-radius: 2px;
}
.input-area-custom .more-options-popup-scroll .more-options-divider {
    display: none !important;
}

