}
/* =================================== */
/* 全局调位置 */
/* =================================== */
:root{
  --wechat-title-x:35px;
  --wechat-title-y:5px;
  --btn-back-translate-x:0px;
  --btn-back-translate-y:3px;
  --btn-info-translate-x:0px;
  --btn-info-translate-y:5px;

  --unread-num-top:13px;
  --unread-num-left:18px;
  --unread-num-font-size:10px;
  --unread-num-font-weight:700;
  --unread-num-padding:0 7px;
  --unread-num-height:18px;

  --voice-btn-x:-13px;
  --voice-btn-y:-5px;
  --voice-btn-size:28px;

  --btn-mic-x:28px;
  --btn-mic-y:0px;
  --btn-sticker-x:26px;
  --btn-sticker-y:0px;
  --btn-ai-send-x:22px;
  --btn-ai-send-y:0px;

  --fake-sticker-x:26px;
  --fake-sticker-y:0px;
  --real-send-x:22px;
  --real-send-y:0px;

  --gen-plus-x:24px;
  --gen-icon-y:49.5%;
  --gen-sticker-x:-16px;
  --gen-sticker-y:50.5%;
  --gen-mic-x:-77px;
  --gen-mic-y:25.8px;
}

/* =================================== */
/* 全局日间模式 */
/* =================================== */
@media (prefers-color-scheme: light) {
