    box-shadow: none !important;
    height: calc(60px + var(--nuo-safe-top)) !important;
    padding: 0 !important;
    position: relative !important;
}

/* 🌟 魔法改造：把原本的标题按钮变成主人的专属头像！ 🌟 */
.nj-chat-tab-header-title-btn {
    display: block !important;
    position: absolute !important;
    left: 16px !important;
    top: calc(10px + var(--nuo-safe-top)) !important;
    width: 38px !important;
    height: 38px !important;
    border-radius: 50% !important; /* 保持完美圆形 */
    background-image: url('https://i.postimg.cc/JngHcZPj/IMG-1538.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    color: transparent !important; /* 隐藏原本的系统文字 */
    margin: 0 !important;
    padding: 0 !important;
}
/* 隐藏多余的系统图标 (注意：十一已经把返回键从这里移除了，不隐藏它啦！) */
.nj-chat-tab-header-title-btn::before, 
.nj-chat-tab-header-title-btn::after {
    display: none !important;
}

/* ✨ 第一层文字：这里改主昵称  ✨ */
.nj-chat-tab-header::before {
    content: '白咪饭';
    position: absolute;
    left: 64px;
    top: calc(10px + var(--nuo-safe-top));
    font-size: 18px;
    font-weight: 500;
    color: #000;
    line-height: 1;
}

/* ✨ 第二层文字：状态 (这里改状态）+ 前置小图标 ✨ */
.nj-chat-tab-header::after {
    content: '我Crush了 >';
    position: absolute;
    left: 64px;
    top: calc(32px + var(--nuo-safe-top)); /* 乖乖排在昵称正下方 */
    font-size: 12px; /* 专属小字号 */
    font-weight: 400;
    color: #000; /* 纯黑色 */
    line-height: 1;

    /* 👇 新增：状态前面的小图标 👇 */
    padding-left: 16px; /* 给图标留出空间，数字越大离文字越远 */
    background-image: url('https://i.postimg.cc/25Rqz4Kp/IMG-1602.png');
    background-size: 14px 14px; /* 图标的大小 */
    background-repeat: no-repeat;
    background-position: left center; /* 图标靠左居中对齐 */
}

/* 🟥 找回的返回键 (红色方框版) 🟥 */
.nj-chat-tab-header-back svg { display: none !important; } /* 隐藏系统自带的箭头 */
.nj-chat-tab-header-back {
    display: block !important; /* 重新显示出来！ */
    position: absolute !important;
    background-color: 0 !important; /* 找不到返回键了就把这里的0改成red */
    width: 20px !important; /* 方框宽度 */
    height: 20px !important; /* 方框高度 */

    /* 👇 在这里调整红色方框的位置！ 👇 */
    /* translate(左右距离, 上下距离) */
    /* 第一个数字：正数向右移，负数向左移 */
    /* 第二个数字：正数向下移，负数向上移 */
    transform: translate(27px, 15px) !important; /* 定位在头像上 */

    left: 0 !important; /* 基础定位点 */
    top: calc(0px + var(--nuo-safe-top)) !important; /* 基础定位点 */
    z-index: 99 !important; /* 保证在最上层不被挡住 */
}

