    background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%238a8a8a" stroke-width="2"><circle cx="11" cy="11" r="6"/><path d="M21 21l-4.35-4.35"/></svg>');
    background-size: 16px;
    background-repeat: no-repeat;
    background-position: calc(50% - 24px) center;
