}

/* ==========================================
   3. 提示栏 (真实图片替换 + 自由调整位置)
========================================== */
.nj-chat-tab-decor-top {
    display: flex !important;
    align-items: center !important;
    padding: 0 20px 12px 20px !important;
    background: var(--qq-gray-blue) !important; /* 统一浅灰蓝 */
    font-size: 13px !important;
    color: #8a8a8a !important;
    /* 右侧箭头 SVG */
    background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23b0b0b0" stroke-width="1.5"><path d="M9 18l6-6-6-6"/></svg>');
    background-size: 16px !important;
    background-repeat: no-repeat !important;
    background-position: calc(100% - 16px) center !important;
}

/* ✨ iPad 真实图片图标 ✨ */
.nj-chat-tab-decor-top::before {
    content: '' !important;
    display: inline-block !important; /* 保证图片绝对能显示出来！ */

    /* 👇 1. 调整图片大小 👇 */
    width: 20px !important; 
    height: 20px !important;

    background-image: url('https://i.postimg.cc/Xv0LBBzr/IMG-1580.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;

    /* 👇 2. 调整图片位置 (上下左右) 👇 */
    /* translate(左右距离, 上下距离) */
    /* 第一个数字：正数向右移，负数向左移 (比如 5px 或 -5px) */
    /* 第二个数字：正数向下移，负数向上移 (比如 2px 或 -2px) */
    transform: translate(0px, 3px) !important; 

    /* 距离右边文字的基础间距 */
    margin-right: 12px !important;
}

/* ✨ 提示栏文字自定义 ✨ */
.nj-chat-tab-decor-top::after {
    content: '已登陆iPad' !important;
    display: inline-block !important;

    /* 👇 调整文字位置 (上下左右) 👇 */
    /* translate(左右距离, 上下距离) */
    /* 第一个数字：正数向右移，负数向左移 */
    /* 第二个数字：正数向下移，负数向上移 */
    transform: translate(0px, 3px) !important; 
}

/* 隐藏便签和分类标题 */
.nj-chat-tab-notes, .nj-chat-tab-section-title {
    display: none !important;
}

/* ==========================================
   4. 聊天列表项 (头像大小 & 间距精细调整版) - 日间模式
========================================== */
.nj-chat-tab-list {
    padding-top: 0px !important;
    background: #ffffff !important; /* 纯黑→纯白 */
}
.nj-chat-item {
    padding: 10px 16px !important; 
    border-bottom: none !important;
    margin: 0 !important;
    background: #ffffff !important; /* 纯黑→纯白 */
    position: relative;
}
.nj-chat-item-avatar {
    /* 👇 1. 调整头像大小 👇 */
    width: 51px !important;  /* 头像宽度，改大改小看这里 */
    height: 51px !important; /* 头像高度，必须和宽度保持一致才能是正圆！ */

    border-radius: 50% !important;

    /* 👇 2. 调整头像与右侧文字（昵称/消息）的左右距离 👇 */
    margin-right: 0px !important; /* 数字越大，头像离右边的文字越远 */
}
.nj-chat-item-name {
    font-size: 16px !important;
    color: #000000 !important; /* 白色→纯黑 */
    font-weight: 400 !important;

    /* 👇 3. 调整昵称和下方消息预览的上下距离 👇 */
    margin-bottom: 4px !important; /* 数字越大，昵称和下面的消息隔得越开，如果不需要可以改成 0px */
}

/* ✨ 专属定制：只给【第一个】聊天项的名字后面加图标 ✨ */
.nj-chat-item:first-child .nj-chat-item-name::after {
    content: '' !important;
    display: inline-block !important;
    background-image: url('https://i.postimg.cc/qqWtzYGw/IMG-1622.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: left center !important; /* 靠左对齐 */

    /* 👇 4. 调整图标大小 👇 */
    width: 60px !important;  /* 图标的宽度，主人按需改 */
    height: 20px !important; /* 图标的高度，主人按需改 */

    /* 👇 5. 调整图标位置 👇 */
    margin-left: 4px !important; /* 图标距离左边名字的距离，紧跟着名字 */
    vertical-align: middle !important; /* 让图标和文字垂直居中对齐 */
    transform: translateY(-2px) !important; /* 上下微调：正数往下移，负数往上移 (比如 -2px) */
}

.nj-chat-item-preview {
    font-size: 13px !important;
    color: #8a8a8a !important; /* 深灰→浅灰 */
}

/* ==========================================
   5. 置顶项特殊处理 (终极物理掩盖法！绝对干净！)
========================================== */
.nj-chat-item-pinned {
    background: var(--nj-msg-card-bg-pinned) !important;
    position: relative !important;
    overflow: hidden !important; /* 防止任何东西漏出来 */
}

/* 💥 第一层：涂改液战术！用同色方块把右边彻底糊死！ 💥 */
.nj-chat-item-pinned::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    right: 0 !important;
    top: 0 !important;
    bottom: 0 !important;
    width: 80px !important; /* 盖住右侧80px的区域，把钉子、时间什么的全埋了 */
    background: var(--nj-msg-card-bg-pinned) !important; /* 和置顶背景色完全一样 */
    z-index: 10 !important; /* 层级调高，死死压住底层 */
}

/* ✨ 第二层：在干净的右边，重新放上主人的图片！ ✨ */
.nj-chat-item-pinned::after {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    background-image: url('https://i.postimg.cc/yxh8L5TG/IMG-1576.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: right center !important;
    pointer-events: none !important;

    /* 👇 调整图片位置 👇 */
    right: 16px !important;
    top: 30% !important;
    transform: translateY(-50%) !important; 
    width: 60px !important;
    height: 30px !important;
    z-index: 11 !important; /* 浮在遮罩层上面，保证清晰可见 */
}

