    --qq-gray-blue: #f3f4f9;

    --nj-msg-chat-bg: #ffffff; /* 列表底色纯白 */
    --nj-msg-bg: #ffffff;
    --nj-msg-text: #000000;
    --nj-msg-text-muted: #8a8a8a;
    --nj-msg-text-time: #b0b3bf;
    --nj-msg-unread-bg: #b0b9c9; 
    --nj-msg-card-bg-pinned: var(--qq-gray-blue); /* 置顶颜色同步 */
    --nj-msg-avatar-radius: 50%;
    --nj-msg-tabbar-bg: #ffffff;
    --nj-msg-tabbar-active: #0099ff;
    --nj-msg-tabbar-inactive: #000000;
