}

.tm-translation-section {
  margin-top: 10px !important;
  background: rgba(255,255,255,0.58) !important;
  border: 1px dashed #cfcfcb !important;
  border-radius: 7px !important;
  overflow: hidden !important;
}

.tm-translation-toggle {
  padding: 7px 10px !important;
  background: rgba(245,245,242,0.82) !important;
  color: #666 !important;
  font-size: 12px !important;
}

.tm-translation-body {
  padding: 10px 12px !important;
  color: #555 !important;
  font-size: 13px !important;
  line-height: 1.55 !important;
}


/* =========================================================
   12. 输入区
   ========================================================= */

.tm-compose {
  background: rgba(250,250,247,0.82) !important;
  border-top: 1px solid rgba(185,185,180,0.55) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  box-shadow: 0 -6px 22px rgba(0,0,0,0.05) !important;
}

.tm-compose-toolbar {
  gap: 7px !important;
}

.tm-regen-btn,
.tm-suggestions-btn {
  background: rgba(255,255,255,0.82) !important;
  border: 1px solid #cececa !important;
  border-radius: 999px !important;
  color: #666 !important;
}

.tm-regen-btn svg,
.tm-suggestions-btn svg {
  color: #666 !important;
  stroke: #666 !important;
}

.tm-regen-btn.active,
.tm-suggestions-btn.active {
  background: #666 !important;
  color: #ffffff !important;
  border-color: #666 !important;
}

.tm-compose-row {
  gap: 8px !important;
}

.tm-input {
  background: #ffffff !important;
  border: 1px solid #d4d4d0 !important;
  border-radius: 10px !important;

  color: #333 !important;
  line-height: 1.5 !important;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.9),
    0 3px 10px rgba(0,0,0,0.04) !important;
}

.tm-input::placeholder {
  color: #aaa !important;
}

.tm-send-btn {
  background: #666 !important;
  border: 1px solid #555 !important;
  border-radius: 10px !important;
  color: #ffffff !important;
  box-shadow: 0 3px 10px rgba(0,0,0,0.12) !important;
}

.tm-send-btn.ready {
  background: #4f4f4f !important;
  color: #ffffff !important;
}


/* =========================================================
   13. 建议回复面板
   ========================================================= */

.tm-suggestions-panel {
  background: rgba(255,255,255,0.9) !important;
  border: 1px solid #d8d8d4 !important;
  border-radius: 12px !important;
  box-shadow: var(--id-shadow) !important;
  overflow: hidden !important;
}

.tm-suggestion-item {
  background: rgba(253,253,251,0.92) !important;
  border-bottom: 1px dashed #d6d6d2 !important;
  padding: 10px 12px !important;
}

.tm-suggestion-item:last-child {
  border-bottom: none !important;
}

.tm-suggestion-direction {
  color: #777 !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 0.4px !important;
}

.tm-suggestion-text {
  color: #444 !important;
  font-size: 13px !important;
  line-height: 1.45 !important;
}

.tm-suggestion-reroll {
  color: #777 !important;
}


/* =========================================================
   14. 右键 / 长按菜单
   ========================================================= */

.tm-context-menu {
  background: rgba(255,255,255,0.96) !important;
  border: 1px solid #d8d8d4 !important;
  border-radius: 10px !important;
  box-shadow: 0 8px 24px rgba(0,0,0,0.12) !important;
}

.tm-context-menu button {
  color: #444 !important;
}

.tm-ctx-delete {
  color: #a55 !important;
}


/* =========================================================
   15. 手机窄屏适配
   ========================================================= */

@media (max-width: 520px) {
  :root {
    --id-card-width: 90vw;
    --id-body-max-height: 420px;

    /* 【可改：手机端头像大小】 */
    --id-avatar-w: 96px;
    --id-avatar-h: 124px;

    /* 【可改：手机端头像位置】 */
    --id-avatar-left: 18px;
    --id-avatar-top: 80px;

    /* 【可改：手机端右侧信息位置】 */
    --id-info-left: 130px;

    --id-header-height: 242px;
  }

  .tm-story {
    padding: 14px 12px 50px 12px !important;
  }

  .tm-para {
    margin: 2px auto !important;
  }

  .tm-para-char,
  .tm-para-user {
    width: var(--id-card-width) !important;
    max-width: var(--id-card-width) !important;
    margin-left: auto !important;
    margin-right: auto !important;
    padding: 9px 12px 9px 12px !important;
  }

  .tc-header,
  .tc-header-user {
    min-height: var(--id-header-height) !important;
    padding: 68px 12px 10px 12px !important;
    margin-bottom: 6px !important;
  }

  .tc-header::before,
  .tc-header-user::before {
    font-size: 15px !important;
    letter-spacing: 0.7px !important;
  }

  .tc-avatar-frame,
  .tc-header-user .tc-avatar-frame-user {
    left: var(--id-avatar-left) !important;
    top: var(--id-avatar-top) !important;
    width: var(--id-avatar-w) !important;
    height: var(--id-avatar-h) !important;
    padding: 1px !important;
  }

  .tc-avatar-badge {
    left: var(--id-avatar-left) !important;
    top: calc(var(--id-avatar-top) + var(--id-avatar-h) + 5px) !important;
    width: var(--id-avatar-w) !important;
    max-width: var(--id-avatar-w) !important;
    font-size: 10px !important;
  }

  .tc-meta-area {
    left: var(--id-info-left) !important;
    right: 20px !important;
    top: var(--id-avatar-top) !important;
    gap: 6px !important;
  }

  .tc-meta-title {
    font-size: 20px !important;
    padding-right: 142px !important;
  }

  .tc-stat {
    font-size: 9px !important;
  }

  .tc-stat[data-label="page"] {
    right: 76px !important;
  }

  .tc-stat[data-label="words"] {
    right: 0 !important;
  }

  .tc-header-user .tc-avatar-badge-user {
    left: var(--id-info-left) !important;
    top: var(--id-avatar-top) !important;
    max-width: calc(100% - 148px) !important;
    font-size: 20px !important;
    line-height: 1.05 !important;
  }

  .tc-header-user .tc-avatar-badge-user::after {
    margin-top: 3px !important;
    font-size: 11px !important;
    line-height: 1.12 !important;
  }

  .tc-header-user .tc-avatar-frame-user::after {
    left: calc(var(--id-info-left) - var(--id-avatar-left)) !important;
    top: 46px !important;
    width: calc(var(--id-card-width) - 155px) !important;
    font-size: 11px !important;
    line-height: 1.12 !important;
  }

  .tm-body-char,
  .tm-body-user {
    font-size: 13px !important;
    padding: 8px 10px 8px 12px !important;
  }
}

/*⁣‍‍‍​‍​​⁠‍‍⁠⁠⁠‍‍​⁠‍‌‌​⁠‍​‌​‍⁠‍⁠⁠⁠‌‍⁠‍​⁠⁠​⁠‌‍‍‍‍⁠‍⁠​‍‌⁠‍‌‌‌‍⁠‍​‍⁠⁠⁣ =========================================================
AO3 章节页整合稳定终版
- 针对不支持变量的全屏软件彻底重写固定高度
- 第一行/第二行栏目变宽敞，修复被状态栏遮挡问题
- 单行平均分布按钮 / 无按钮外框
- 标题渐变 / 标题细红线 / 纸张感
========================================================= */

/* ===== 变量 ===== */
:root {
--ao3-red: #900;
--ao3-red-dark: #7a0000;
--ao3-bg: #ece4da;
--ao3-paper: #fffdfa;
--ao3-paper-soft: #fcf8f4;
--ao3-paper-2: #f4ece4;
--ao3-text: #1f1f1f;
--ao3-text-2: #2b2b2b;
--ao3-soft: #555;
--ao3-line: #d8c8bc;
--ao3-line-dark: #c9b7aa;
--ao3-quote: #f3e7dc;
--ao3-link: #900;
--ao3-link-hover: #b30000;
}

/* ===== 全局 ===== */
#this-moment-screen {
background: var(--ao3-bg) !important;
color: var(--ao3-text) !important;
font-family:
Georgia,
"Noto Sans CJK SC",
"Noto Sans SC",
"Source Han Sans SC",
"PingFang SC",
"Hiragino Sans GB",
"Microsoft YaHei",
sans-serif !important;
font-synthesis: none !important;
}

.tm-bg-overlay {
background:
linear-gradient(to bottom, rgba(255,255,255,.16), rgba(255,255,255,.08)),
var(--ao3-bg) !important;
}

.tm-bg-image {
display: none !important;
}

/* ===== 顶栏 ===== */
.tm-header {
position: relative !important;
display: grid !important;
grid-template-columns: auto 1fr auto !important;
/* 👇 两栏的高度变大了：54px 和 40px */
grid-template-rows: 54px 40px !important;
grid-template-areas:
"left left right"
"chars chars chars" !important;
column-gap: 8px !important;
row-gap: 0 !important;
align-items: center !important;
/* 👇 给顶部状态栏留出 35px 的死空间 */
padding: 35px 0 0 0 !important;
/* 35 + 54 + 40 = 129px */
min-height: 129px !important;
border-bottom: none !important;
box-sizing: border-box !important;
overflow: hidden !important;
z-index: 30 !important;
background: linear-gradient(
to bottom,
#fdfbf7 0,
#fdfbf7 89px,
var(--ao3-red) 89px,
var(--ao3-red) 100%
) !important;
box-shadow: inset 0 2px 0 #900 !important;
}

.tm-header::after {
grid-area: left !important;
content: "Archive of Our Own" !important;
color: var(--ao3-red) !important;
font-weight: 700 !important;
font-size: 18px !important;
font-family: Garamond, Georgia, serif !important;
white-space: nowrap !important;
background-image: url('https://i.postimg.cc/9fhMD3Zx/Screenshot-20260409-121451-com-xingin-xhs-Note-Detail-Activity-edit-3579091065401294.jpg') !important;
background-size: 28px 28px !important;
background-repeat: no-repeat !important;
background-position: left center !important;
padding-left: 36px !important;
line-height: 1 !important;
height: 54px !important;
display: flex !important;
align-items: center !important;
justify-self: start !important;
margin-left: 12px !important;
align-self: center !important;
}

.tm-header::before {
display: none !important;
}

.tm-header-right {
grid-area: right !important;
display: flex !important;
align-items: center !important;
justify-content: flex-end !important;
gap: 12px !important;
height: 54px !important;
padding: 0 12px !important;
background: transparent !important;
position: relative !important;
z-index: 2 !important;
}

.tm-header-right .tm-btn-icon {
display: flex !important;
align-items: center !important;
justify-content: center !important;
background: transparent !important;
border: none !important;
color: var(--ao3-red) !important;
font-size: 16px !important;
font-weight: 700 !important;
padding: 0 !important;
min-width: auto !important;
}

.tm-header-right .tm-btn-icon svg {
display: none !important;
}

.tm-header-right .tm-btn-icon:first-child::before {
content: "Browse" !important;
color: var(--ao3-red) !important;
font-size: 16px !important;
font-weight: 700 !important;
}

.tm-header-right .tm-btn-icon:nth-child(2):before {
content: "About" !important;
color: var(--ao3-red) !important;
font-size: 16px !important;
font-weight: 700 !important;
}

/* 角色区 */
.tm-header-center {
grid-area: chars !important;
display: flex !important;
align-items: center !important;
justify-content: center !important;
gap: 8px !important;
width: 100% !important;
min-width: 0 !important;
margin: 0 !important;
padding: 0 56px !important;
height: 40px !important;
box-sizing: border-box !important;
background: transparent !important;
position: relative !important;
z-index: 1 !important;
}

.tm-header-center .tm-header-name {
color: #fff !important;
font-size: 14px !important;
font-weight: 700 !important;
text-align: center !important;
white-space: nowrap !important;
overflow: hidden !important;
text-overflow: ellipsis !important;
max-width: min(60vw, 320px) !important;
}

.tm-header-center .tm-header-avatar {
width: 24px !important;
height: 24px !important;
border: 1px solid #fff !important;
flex: 0 0 24px !important;
}

.tm-top-vs {
color: rgba(255,255,255,.82) !important;
}

/* 返回键 */
.tm-header>.tm-btn-icon:first-child {
position: absolute !important;
left: 12px !important;
top: 109px !important;
transform: translateY(-50%) !important;
width: 36px !important;
height: 28px !important;
display: flex !important;
align-items: center !important;
justify-content: center !important;
background: transparent !important;
border: none !important;
color: var(--ao3-red) !important;
fill: var(--ao3-red) !important;
z-index: 3 !important;
}

.tm-header>.tm-btn-icon:first-child svg {
color: var(--ao3-red) !important;
fill: var(--ao3-red) !important;
}

/* ===== 故事区 ===== */
.tm-story {
background: transparent !important;
padding: 18px 14px 28px !important;
box-sizing: border-box !important;
}

.tm-para {
width: min(100%, 860px) !important;
margin: 0 auto 2.1em auto !important;
padding: 0 !important;
box-sizing: border-box !important;
}

.tm-para-char,
.tm-para-user {
position: relative !important;
overflow: hidden !important;
background: var(--ao3-paper) !important;
border: 1px solid var(--ao3-line) !important;
border-radius: 0 !important;
box-shadow:
0 1px 0 rgba(120, 80, 60, 0.04),
0 3px 10px rgba(120, 80, 60, 0.06) !important;
padding: 1.1em 1.2em 1.2em !important;
margin: 0 !important;
}

.tm-para-user {
background: var(--ao3-paper-soft) !important;
border-color: #d9c9bd !important;
}

.tm-para-char::before,
.tm-para-user::before {
content: "" !important;
position: absolute !important;
left: 0 !important;
right: 0 !important;
top: 0 !important;
height: 18px !important;
background: linear-gradient(
to bottom,
rgba(255,255,255,0.28),
rgba(255,255,255,0)
) !important;
pointer-events: none !important;
}

/* ===== 章节头 ===== */
.tc-header {
position: relative !important;
background: transparent !important;
border-bottom: none !important;
padding: 0 0 .9em 0 !important;
margin: 0 0 1.1em 0 !important;
}

.tc-header::after {
content: "" !important;
display: block !important;
width: 100% !important;
height: 1px !important;
margin-top: 10px !important;
background: linear-gradient(
to right,
transparent 0%,
#900 18%,
#900 82%,
transparent 100%
) !important;
opacity: 0.75 !important;
}

.tc-header-user {
display: none !important;
}

.tc-avatar-frame {
border: 1px solid #c8b9ae !important;
border-radius: 0 !important;
box-shadow: none !important;
width: 62px !important;
height: 62px !important;
}

.tc-avatar-badge {
color: var(--ao3-soft) !important;
font-size: 11px !important;
}

/* ❤️❤️❤️ 标题位置：改这里 ❤️❤️❤️ */
.tc-meta-title {
font-size: 0 !important;
}

.tc-meta-title::after {
content: "The Hour We Kept" !important;
display: block !important;
background: linear-gradient(180deg, #a10000 0%, #900 45%, #7a0000 100%) !important;
-webkit-background-clip: text !important;
background-clip: text !important;
-webkit-text-fill-color: transparent !important;
text-shadow: 0 1px 0 rgba(255,255,255,0.35) !important;
font-family: Georgia, "Times New Roman", serif !important;
font-size: 1.68rem !important;
line-height: 1.24 !important;
font-weight: 400 !important;
letter-spacing: 0.2px !important;
}

/* ❤️❤️❤️ 作者位置：改这里 ❤️❤️❤️ */
.tc-meta-subtitle {
min-height: 18px !important;
}

.tc-meta-subtitle::before {
content: "by us" !important;
display: inline-block !important;
color: var(--ao3-red-dark) !important;
font-family: Georgia, "Times New Roman", serif !important;
font-size: .98rem !important;
font-style: italic !important;
}

/* stats */
.tc-meta-stats {
gap: 6px !important;
flex-wrap: wrap !important;
}

.tc-stat {
background: var(--ao3-paper-2) !important;
color: var(--ao3-red) !important;
border: 1px solid #d8c4b8 !important;
border-radius: 0 !important;
font-size: 12px !important;
padding: 2px 8px !important;
}

.tc-stat[data-label="page"] {
font-size: 12px !important;
color: var(--ao3-red) !important;
}

.tc-stat[data-label="page"]::before {
content: "Chapter " !important;
color: var(--ao3-red) !important;
}

.tc-divider-text::before {
content: "" !important;
}

/* ===== 正文 ===== */
.tm-body-char,
.tm-body-user {
width: 100% !important;
max-width: 100% !important;
margin: 0 auto !important;
color: var(--ao3-text) !important;
background: transparent !important;
font-family:
Georgia,
"Noto Sans CJK SC",
"Noto Sans SC",
"Source Han Sans SC",
"PingFang SC",
"Hiragino Sans GB",
"Microsoft YaHei",
sans-serif !important;
font-size: 17px !important;
line-height: 1.82 !important;
font-weight: 400 !important;
letter-spacing: 0 !important;
text-align: left !important;
box-sizing: border-box !important;
}

.tm-body-char .tm-para-block,
.tm-body-user .tm-para-block {
margin: 0 0 1em 0 !important;
padding: 0 !important;
text-indent: 2em !important;
}

.tm-body-char .tm-para-block:first-child,
.tm-body-user .tm-para-block:first-child {
margin-top: 0 !important;
}

.tm-body-char {
color: #1e1e1e !important;
}

.tm-body-user {
color: #2b2b2b !important;
}

/* ===== 文本格式增强 ===== */
.tm-body-char *,
.tm-body-user * {
max-width: 100%;
}

.tm-bold,
.tm-body-char strong,
.tm-body-user strong,
.tm-body-char b,
.tm-body-user b {
font-weight: 700 !important;
color: #7a0000 !important;
background: rgba(153, 0, 0, 0.06) !important;
padding: 0 .08em !important;
}

.tm-action,
.tm-body-char em,
.tm-body-user em,
.tm-body-char i,
.tm-body-user i {
font-style: italic !important;
color: #4a3b36 !important;
}

.tm-del,
.tm-body-char del,
.tm-body-user del,
.tm-body-char s,
.tm-body-user s {
color: #777 !important;
text-decoration: line-through !important;
text-decoration-thickness: 1px !important;
opacity: .92 !important;
}

.tm-body-char u,
.tm-body-user u,
.tm-body-char ins,
.tm-body-user ins,
.tm-body-char .tm-underline,
.tm-body-user .tm-underline {
text-decoration-line: underline !important;
text-decoration-style: wavy !important;
text-decoration-color: #b30000 !important;
text-decoration-thickness: 1.5px !important;
text-underline-offset: 2px !important;
}

.tm-body-char mark,
.tm-body-user mark,
.tm-body-char .tm-highlight,
.tm-body-user .tm-highlight {
background: #f7e3cf !important;
color: #7a0000 !important;
padding: 0 .12em !important;
}

.tm-body-char big,
.tm-body-user big,
.tm-body-char .tm-large,
.tm-body-user .tm-large {
font-size: 1.18em !important;
line-height: 1.65 !important;
}

.tm-body-char small,
.tm-body-user small,
.tm-body-char .tm-small,
.tm-body-user .tm-small {
font-size: .88em !important;
color: #666 !important;
}

.tm-body-char [style*="color:"],
.tm-body-user [style*="color:"] {
font-weight: 600 !important;
}

.tm-body-char a,
.tm-body-user a {
color: var(--ao3-link) !important;
text-decoration: underline !important;
}

.tm-body-char a:hover,
.tm-body-user a:hover {
color: var(--ao3-link-hover) !important;
}

.tm-quote-block {
background: var(--ao3-quote) !important;
border-left: 4px solid var(--ao3-red) !important;
padding: .85em 1em !important;
margin: 1em 0 !important;
line-height: 1.8 !important;
text-indent: 0 !important;
color: #252525 !important;
}

.tm-quote-block .tm-para-block,
.tm-body-char .tm-quote-block,
.tm-body-user .tm-quote-block {
text-indent: 0 !important;
}

.tm-para:has(.tm-para-user) .tm-para-user {
border-left: 3px solid #c9b3a5 !important;
}

.tm-para:has(.tm-para-user) .tm-body-user .tm-para-block {
text-indent: 1.5em !important;
}

/* ===== 历史按钮 ===== */
.tm-load-more {
display: block !important;
margin: 1.5em auto 2em auto !important;
background: #f4ece4 !important;
color: var(--ao3-red) !important;
border: 1px solid #d6c3b7 !important;
border-radius: 0 !important;
font-family: inherit !important;
padding: .5em 1em !important;
}

/* ===== 生成中文案 ===== */
.tm-loading-text {
font-size: 0 !important;
}

.tm-loading-text::before {
content: "The story continues..." !important;
font-size: 13px !important;
color: #900 !important;
font-family: Georgia, "Times New Roman", serif !important;
font-style: italic !important;
}

/* ===== 底栏 ===== */
.tm-compose {
background: #ece4da !important;
border-top: 1px solid rgba(144, 0, 0, 0.45) !important;
/* 底部防遮挡写死 20px */
padding: 1px 0 20px !important;
min-height: auto !important;
box-shadow: none !important;
