:root {
  --netease-bg: #ffffff;
  --netease-white: #ffffff;
  --netease-red: #ff3a3a;
  --netease-blue: #5a7a9a;
  --netease-divider: #e8e8e8;
  --netease-text: #222222;
  --netease-text-secondary: #888888;
  --netease-text-light: #bbbbbb;
}

#this-moment-screen {
  background: var(--netease-bg) !important;
}
.tm-bg-overlay, .tm-bg-image { display: none !important; }

/* ================= 顶部导航栏 ================= */
.tm-header {
  height: 105px !important;
  background: var(--netease-white) !important;
  backdrop-filter: blur(10px) !important;
  border-bottom: 1px solid var(--netease-divider) !important;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04) !important;
  position: relative !important;
  display: flex !important;
  align-items: flex-end !important;
  justify-content: space-between !important;
  padding: 0 10px 35px 10px !important;
}

/* 「评论」带下划线 - 位置偏左 */
.tm-header-center::before {
  content: '评论';
  position: absolute;
  top: 50%;
  left: 60%;
  transform: translate(calc(-50% - 32px), -50%);
  font-size: 17px;
  color: #222222;
  font-weight: 500;
  pointer-events: none;
  white-space: nowrap;
  text-decoration: underline;
