* { margin: 0; padding: 0; box-sizing: border-box; }

/* ⭐ 定义全局变量 */
:root {
  --theme-color: #ffffff; /* 字体颜色 */
  --box-color: #ffffff;   /* 背后方框颜色 */
  --tear-color: #ffffff;  /* 泪滴颜色 */
}

body {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: "PingFang SC", "Microsoft YaHei", "Times New Roman", serif;
  overflow: hidden;
  background: transparent;
}

.widget-container {
  width: 100%;
  height: 100%;
  background: transparent; /* 保持纯透明底色 */
  padding: 8px 12px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  border-radius: 20px;
}

/* 顶部法文 */
.top-text {
  align-self: flex-end;
  text-align: right;
  margin-right: 2px;
  font-size: 8px;
  letter-spacing: 0.5px;
  color: var(--theme-color);
  font-family: "Times New Roman", serif;
  line-height: 1.2;
  margin-top: 2px;
}

/* 图片交叠区 */
.images-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  margin: 0;
  height: 80px;
}

.img-item {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.img-item:not(:first-child) { margin-left: -28px; }
.img-item:nth-child(1) { z-index: 1; margin-top: 8px; }
.img-item:nth-child(2) { z-index: 3; margin-top: 0px; }
.img-item:nth-child(3) { z-index: 2; margin-top: 10px; }

.img-circle {
  width: 70px;
  height: 70px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 1px 1px 6px rgba(0,0,0,0.3);
  border: 1.5px solid rgba(255, 255, 255, 0.7);
  background-color: rgba(255,255,255,0.1);
}

.img-circle img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* 中间图旋转 */
.img-item:nth-child(2) .img-circle { animation: spin 8s linear infinite; }
@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }

/* 装饰线框 */
.deco-box { position: absolute; pointer-events: none; z-index: -1; }
.deco-left-1  { width: 55px; height: 75px; top: -12px; left: -12px; border: 1px solid var(--box-color); opacity: 0.6; transform: rotate(-2deg); }
.deco-left-2  { width: 42px; height: 58px; top: 8px;   left: -2px;  border: 1px solid var(--box-color); opacity: 0.3; transform: rotate(1deg);  }
.deco-right-1 { width: 65px; height: 55px; bottom: -12px; right: -12px; border: 1px solid var(--box-color); opacity: 0.4; transform: rotate(1.5deg); }
.deco-right-2 { width: 48px; height: 42px; bottom: -5px;  right: 5px;   border: 1px solid var(--box-color); opacity: 0.7; transform: rotate(-1deg); }

/* 一滴泪 - ⭐ 改为独立变量控制 */
.dynamic-right {
  position: absolute;
  top: 10%;
  right: 18px;
  width: 10px;
  height: 10px;
  background-color: var(--tear-color); /* ⭐ 现在跟随 tearColor 字段 */
  border-radius: 0 50% 50% 50%;
  transform: rotate(45deg);
  animation: teardrop 3s ease-in infinite;
  z-index: 0;
}

@keyframes teardrop {
  0%   { transform: translateY(0px) rotate(45deg) scale(0.8); opacity: 0;   }
  15%  { opacity: 0.9; }
  70%  { opacity: 0.8; }
