/* =========================================
   🌟 角标区：接入独立的字体和颜色变量
========================================= */
.badge-count {
  position: absolute; top: 0px; right: -4px; 
  /* 颜色和字号由 JS 变量接管 */
  color: var(--count-color);
  font-size: var(--count-size); 
  font-weight: 700;
  padding: 1.5px 5px; border-radius: 9px;
  letter-spacing: 0.5px; z-index: 10;
  display: flex; align-items: center; justify-content: center;
}

.badge-text {
  opacity: 0.5; /* 保持偏淡的视觉权重 */
}

.badge-count::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  backdrop-filter: blur(15px); -webkit-backdrop-filter: blur(15px);
  border-radius: 9px; z-index: -2;
}

.badge-count::after {
  content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--current-bg); opacity: 0.55; 
  border-radius: 9px; z-index: -1;
}

.badge-border {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  /* 边框颜色跟随角标字体的颜色 */
  border: 0.5px solid var(--count-color); 
  opacity: 0.5; 
  border-radius: 9px; pointer-events: none;
}

.badge-icon-wrapper {
  position: absolute; bottom: -2px; right: -2px;
  width: 18px; height: 18px; border-radius: 5px; 
