.stage-box {
  width: 100%;
  flex: 1;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  perspective: 700px;
  transform-style: preserve-3d;
}

/* 完美自适应卡片 */
.card-item {
  position: absolute;
  width: clamp(65px, 22%, 95px);
  aspect-ratio: 1 / 1.18;
  background-color: rgba(255, 255, 255, 0.65);

  /* 🌟 卡片毛玻璃特效 */
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);

  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 6px;
  box-sizing: border-box;
  transition: transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1), opacity 0.4s ease, z-index 0.4s step-start;
  cursor: pointer;

  /* 🌟 终极防溢出 Hack：切断边缘渲染泄露 */
  overflow: hidden;
  background-clip: padding-box;
  isolation: isolate;

  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

.img-wrap {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 6px;
  overflow: hidden;
  background: rgba(0,0,0,0.05);
  flex-shrink: 0;
}

.card-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

